items.solution:
function rankCandidates(candidates, weights) {
  const score = (c) =>
    c.familiarity * weights.familiarity +
    c.maturity * weights.maturity +
    c.migrationCost * weights.migrationCost +
    c.strategicFit * weights.strategicFit;
  return [...candidates]
    .sort((a, b) => score(b) - score(a))
    .map((c) => c.name);
}

